import RetrieveMetadataInstance from './services/wado/retrieveMetadataInstance.js';

const moduleName = 'RetrieveInstanceMetadata';
// Cache for promises. Prevents unnecessary subsequent calls to the server
const InstanceMetaDataPromises = new Map();

/**
 * Retrieves image metadata
 *
 * @param {Object} server Object with server configuration parameters
 * @param {string} StudyInstanceUID The UID of the Study to be retrieved
 * @param {string} SeriesInstanceUID The UID of the Study to be retrieved
 * @param {string} SOPInstanceUID The UID of the Study to be retrieved
 * @returns {Promise} that will be resolved with the metadata or rejected with the error
 */
export function retrieveInstanceMetadata(
  server,
  StudyInstanceUID,
  SeriesInstanceUID,
  SOPInstanceUID
) {
  if (!server) {
    throw new Error(`${moduleName}: Required 'server' parameter not provided.`);
  }
  if (!StudyInstanceUID) {
    throw new Error(
      `${moduleName}: Required 'StudyInstanceUID' parameter not provided.`
    );
  }
  if (!SeriesInstanceUID) {
    throw new Error(
      `${moduleName}: Required 'SeriesInstanceUID' parameter not provided.`
    );
  }
  if (!SOPInstanceUID) {
    throw new Error(
      `${moduleName}: Required 'SOPInstanceUID' parameter not provided.`
    );
  }

  // Already waiting on result? Return cached promise
  if (InstanceMetaDataPromises.has(SOPInstanceUID)) {
    return InstanceMetaDataPromises.get(SOPInstanceUID);
  }

  // Create a promise to handle the data retrieval
  const promise = RetrieveMetadataInstance(
    server,
    StudyInstanceUID,
    SeriesInstanceUID,
    SOPInstanceUID
  );

  // Store the promise in cache
  InstanceMetaDataPromises.set(SOPInstanceUID, promise);

  return promise;
}
