import { api } from 'dicomweb-client';
import DICOMWeb from '../../../DICOMWeb/';
import { createStudyFromSOPInstanceList } from './studyInstanceHelpers';
import RetrieveMetadataLoaderInstance from './retrieveMetadataLoaderInstance';

import errorHandler from '../../../errorHandler';
import getXHRRetryRequestHook from '../../../utils/xhrRetryRequestHook';

/**
 * Class for sync load of study metadata.
 * It inherits from RetrieveMetadataLoader
 *
 * A list of loaders (getLoaders) can be created so, it will be applied a fallback load strategy.
 * I.e Retrieve metadata using all loaders possibilities.
 */
export default class RetrieveMetadataInstanceLoaderSync extends RetrieveMetadataLoaderInstance {
  getOptions() {
    const {
      studyInstanceUID,
      seriesInstanceUID,
      sopInstanceUID,
      filters,
    } = this;

    const options = {
      studyInstanceUID,
      seriesInstanceUID,
      sopInstanceUID,
      filters,
    };

    return options;
  }

  /**
   * @returns {Array} Array of loaders. To be consumed as queue
   */
  *getLoaders() {
    const loaders = [];
    const {
      studyInstanceUID,
      seriesInstanceUID,
      sopInstanceUID,
      client,
    } = this;

    loaders.push(
      client.retrieveInstanceMetadata.bind(client, {
        studyInstanceUID,
        seriesInstanceUID,
        sopInstanceUID,
      })
    );

    yield* loaders;
  }

  configLoad() {
    const { server } = this;
    const client = new api.DICOMwebClient({
      url: server.wadoRoot,
      headers: DICOMWeb.getAuthorizationHeader(server),
      errorInterceptor: errorHandler.getHTTPErrorHandler(),
      requestHooks: [getXHRRetryRequestHook()],
    });

    this.client = client;
  }

  async load(preLoadData) {
    const loaders = this.getLoaders();
    const result = this.runLoaders(loaders);
    return result;
  }

  async posLoad(loadData) {
    const { server } = this;
    return createStudyFromSOPInstanceList(server, loadData);
  }
}
