import log from '../log.js';
import { retrieveInstanceMetadata } from './retrieveInstanceMetadata';

/**
 * Retrieves metaData for instance.
 *
 * This function calls retrieveInstanceMetadata.
 *
 * @param {Object} server Object with server configuration parameters
 * @param {string} studyInstanceUIDs The UIDs of the Studies to be retrieved
 * @param {string} seriesInstanceUIDs The UIDs of the Series to be retrieved
 * @param {string} sopInstanceUIDs The UIDs of the Instances to be retrieved
 * @returns {Promise} that will be resolved with the metadata or rejected with the error
 */
export default function retrieveInstancesMetadata(
  server,
  studyInstanceUIDs,
  filters,
  separateSeriesInstanceUIDFilters = false
) {
  // Create an empty array to store the Promises for each metaData retrieval call
  const promises = [];

  const {
    seriesInstanceUID: SeriesInstanceUID,
    sopInstanceUID: SOPInstanceUID,
  } = filters;
  // Loop through the array of studyInstanceUIDs
  studyInstanceUIDs.forEach(function(StudyInstanceUID) {
    // Send the call and resolve or reject the related promise based on its outcome
    const promise = retrieveInstanceMetadata(
      server,
      StudyInstanceUID,
      SeriesInstanceUID,
      SOPInstanceUID
    );

    // Add the current promise to the array of promises
    promises.push(promise);
  });

  // When all of the promises are complete, this callback runs
  const promise = Promise.all(promises);

  // Warn the error on console if some retrieval failed
  promise.catch(error => log.warn(error));

  return promise;
}
