import './StudyList.styl';

import React from 'react';
import classNames from 'classnames';
import TableSearchFilter from './TableSearchFilter.js';
import PropTypes from 'prop-types';
import { StudyListLoadingText } from './StudyListLoadingText.js';
import { useTranslation } from 'react-i18next';

/**
 *
 *
 * @param {*} props
 * @returns
 */
function StudyList(props) {
  const {
    isLoading,
    hasError,
    studies,
    sort,
    onSort: handleSort,
    filterValues,
    onFilterChange: handleFilterChange,
    onSelectItem: handleSelectItem,
    studyListDateFilterNumDays,
    displaySize,
  } = props;
  const { t, ready: translationsAreReady } = useTranslation('StudyList');

  const relianceTableMeta = [
    {
      displayText: t('AccessionNumber'),
      fieldName: 'AccessionNumber',
      inputType: 'text',
      size: 240,
    },
    {
      displayText: t('Fecha de recepción'),
      fieldName: 'ReceivedDate',
      inputType: 'date-range',
      size: 60,
    },
    {
      displayText: t('Fecha de diagnóstico'),
      fieldName: 'DiagnoseDate',
      inputType: 'date-range',
      size: 60,
    },
    {
      displayText: t('TimesLabeled'),
      fieldName: 'TimesLabeled',
      inputType: 'text',
      size: 60,
    },
  ];

  const tableMeta = relianceTableMeta;

  const totalSize = tableMeta
    .map(field => field.size)
    .reduce((prev, next) => prev + next);

  return translationsAreReady ? (
    <table className="table table--striped table--hoverable">
      <colgroup>
        {tableMeta.map((field, i) => {
          const size = field.size;
          const percentWidth = (size / totalSize) * 100.0;

          return <col key={i} style={{ width: `${percentWidth}%` }} />;
        })}
      </colgroup>
      <thead className="table-head">
        <tr className="filters">
          <TableSearchFilter
            meta={tableMeta}
            values={filterValues}
            onSort={handleSort}
            onValueChange={handleFilterChange}
            sortFieldName={sort.fieldName}
            sortDirection={sort.direction}
            studyListDateFilterNumDays={studyListDateFilterNumDays}
          />
        </tr>
      </thead>
      <tbody className="table-body" data-cy="study-list-results">
        {/* I'm not in love with this approach, but it's the quickest way for now
         *
         * - Display different content based on loading, empty, results state
         *
         * This is not ideal because it create a jump in focus. For loading especially,
         * We should keep our current results visible while we load the new ones.
         */}
        {/* LOADING */}
        {isLoading && (
          <tr className="no-hover">
            <td colSpan={tableMeta.length}>
              <StudyListLoadingText />
            </td>
          </tr>
        )}
        {!isLoading && hasError && (
          <tr className="no-hover">
            <td colSpan={tableMeta.length}>
              <div className="notFound">
                {t('There was an error fetching studies')}
              </div>
            </td>
          </tr>
        )}
        {/* EMPTY */}
        {!isLoading && !studies.length && (
          <tr className="no-hover">
            <td colSpan={tableMeta.length}>
              <div className="notFound">{t('No matching results')}</div>
            </td>
          </tr>
        )}
        {!isLoading &&
          studies.map((study, index, array) => (
            <TableRow
              key={`${study.StudyInstanceUID}-${study.SeriesInstanceUID}-${study.SOPInstanceUID}-${index}`}
              //onClick={StudyInstanceUID => handleSelectItem(StudyInstanceUID)}
              onClick={(
                previousStudyIdentificators,
                actualStudyIdentificators,
                nextStudyIdentificators,
                filterValues,
              ) =>
                handleSelectItem(
                  previousStudyIdentificators,
                  actualStudyIdentificators,
                  nextStudyIdentificators,
                  filterValues
                )
              }
              AccessionNumber={study.AccessionNumber || ''}
              modalities={study.modalities}
              PatientID={study.PatientID || ''}
              PatientName={study.PatientName || ''}
              StudyDate={study.StudyDate}
              previousStudyIdentificators={
                index > 0
                  ? {
                      studyInstanceUID: array[index - 1].StudyInstanceUID || '',
                      seriesInstanceUID:
                        array[index - 1].SeriesInstanceUID || '',
                      sopInstanceUID: array[index - 1].SOPInstanceUID || '',
                    }
                  : undefined
              }
              actualStudyIdentificators={{
                studyInstanceUID: study.StudyInstanceUID || '',
                seriesInstanceUID: study.SeriesInstanceUID || '',
                sopInstanceUID: study.SOPInstanceUID || '',
              }}
              nextStudyIdentificators={
                index < array.length - 1
                  ? {
                      studyInstanceUID: array[index + 1].StudyInstanceUID || '',
                      seriesInstanceUID:
                        array[index + 1].SeriesInstanceUID || '',
                      sopInstanceUID: array[index + 1].SOPInstanceUID || '',
                    }
                  : undefined
              }
              StudyDescription={study.StudyDescription || ''}
              DiagnoseDate={study.DiagnoseDate || ''}
              ReceivedDate={study.ReceivedDate || ''}
              TimesLabeled={study.TimesLabeled || 0}
              displaySize={displaySize}
            />
          ))}
      </tbody>
    </table>
  ) : null;
}

StudyList.propTypes = {
  isLoading: PropTypes.bool.isRequired,
  hasError: PropTypes.bool.isRequired,
  studies: PropTypes.array.isRequired,
  onSelectItem: PropTypes.func.isRequired,
  // ~~ SORT
  sort: PropTypes.shape({
    fieldName: PropTypes.string,
    direction: PropTypes.oneOf(['desc', 'asc', null]),
  }).isRequired,
  onSort: PropTypes.func.isRequired,
  // ~~ FILTERS
  filterValues: PropTypes.shape({
    PatientName: PropTypes.string,
    PatientID: PropTypes.string,
    AccessionNumber: PropTypes.string.isRequired,
    StudyDate: PropTypes.string,
    modalities: PropTypes.string,
    StudyDescription: PropTypes.string,
    patientNameOrId: PropTypes.string,
    accessionOrModalityOrDescription: PropTypes.string,
    allFields: PropTypes.string,
    studyDateTo: PropTypes.any,
    studyDateFrom: PropTypes.any,
    diagnoseDateTo: PropTypes.any,
    diagnoseDateFrom: PropTypes.any,
    TimesLabeled: PropTypes.number,
  }).isRequired,
  onFilterChange: PropTypes.func.isRequired,
  studyListDateFilterNumDays: PropTypes.number,
  displaySize: PropTypes.string,
};

StudyList.defaultProps = {};

// Gehitu isDiagnosed
function TableRow(props) {
  const {
    AccessionNumber,
    isHighlighted,
    modalities,
    PatientID,
    PatientName,
    StudyDate,
    StudyDescription,
    previousStudyIdentificators,
    actualStudyIdentificators,
    nextStudyIdentificators,
    filterValues,
    DiagnoseDate,
    ReceivedDate,
    TimesLabeled,
    onClick: handleClick,
    displaySize,
  } = props;

  const { t } = useTranslation('StudyList');

  const relianceRowTemplate = (
    // AccessionNumber
    <tr
      onClick={() =>
        handleClick(
          previousStudyIdentificators,
          actualStudyIdentificators,
          nextStudyIdentificators,
          filterValues
        )
      }
      //onClick={() => handleClick(StudyInstanceUID)}
      className={classNames({ active: isHighlighted })}
      //style={{ cursor: 'pointer' }}
    >
      <td style={{ textAlign: 'center' }}>
        <div>{AccessionNumber}</div>
      </td>
      <td style={{ textAlign: 'center' }}>
        <div>{ReceivedDate}</div>
      </td>
      <td style={{ textAlign: 'center' }}>
        <div>{DiagnoseDate}</div>
      </td>
      <td style={{ textAlign: 'center' }}>
        <div>{TimesLabeled}</div>
      </td>
    </tr>
  );

  const rowTemplate = relianceRowTemplate;

  return rowTemplate;
}

TableRow.propTypes = {
  AccessionNumber: PropTypes.string.isRequired,
  isHighlighted: PropTypes.bool,
  modalities: PropTypes.string,
  PatientID: PropTypes.string.isRequired,
  PatientName: PropTypes.string.isRequired,
  StudyDate: PropTypes.string.isRequired,
  StudyDescription: PropTypes.string.isRequired,
  previousStudyIdentificators: PropTypes.shape({
    studyInstanceUID: PropTypes.string,
    seriesInstanceUID: PropTypes.string,
    sopInstanceUID: PropTypes.string,
  }),
  actualStudyIdentificators: PropTypes.shape({
    studyInstanceUID: PropTypes.string,
    seriesInstanceUID: PropTypes.string,
    sopInstanceUID: PropTypes.string,
  }).isRequired,
  nextStudyIdentificators: PropTypes.shape({
    studyInstanceUID: PropTypes.string,
    seriesInstanceUID: PropTypes.string,
    sopInstanceUID: PropTypes.string,
  }),
  filterValues: PropTypes.object,
  DiagnoseDate: PropTypes.string.isRequired,
  displaySize: PropTypes.string,
};

TableRow.defaultProps = {
  isHighlighted: false,
};

export { StudyList };
